import { connect } from "node:net";

import type { WidgetContext, WidgetFieldValue, WidgetQueryResult } from "../_lib/widget_context";

// Who's on a Project Zomboid server. The card folds back to the plain one while nobody is on.
//
// The server's console (RCON) answers players with who's on. The image starts it on RCON_PORT
// (27015) with RCON_PASSWORD, both in the container's environment; the script doesn't publish it,
// so it's reached at the container's own address on its compose network, which the HexOS container
// opens from the host's network and nothing off the box can. The limit is the image's MAX_PLAYERS.
// A box without the Docker socket, or a server still starting, keeps the plain card.

const DOCKER_SOCKET = "/var/run/docker.sock";
/** Docker and the console share the widget's 5 s timeout, so a stuck one reads as nobody on. */
const DOCKER_TIMEOUT_MS = 1500;
const RCON_TIMEOUT_MS = 2500;

// The console's packet types (the Source RCON protocol the server speaks)
const LOGIN = 3;
const COMMAND = 2;
const LOGIN_ANSWER = 2;
/** Far above any answer this widget asks for; a longer one is a stream it shouldn't trust. */
const MAX_PACKET = 1 << 16;

/** The names in players' answer: "Players connected (2): " then "-alex" a line. */
export function connectedPlayers(answer: string): string[] {
  return answer
    .split("\n")
    .map((line) => /^\s*-(.+?)\s*$/.exec(line)?.[1])
    .filter((name): name is string => !!name);
}

/** Who's online in a line: "Alex, Steve, and 3 more". */
export function playersLine(names: string[]): string {
  if (names.length <= 2) return names.join(" and ");
  if (names.length === 3) return `${names[0]}, ${names[1]}, and ${names[2]}`;
  return `${names[0]}, ${names[1]}, and ${names.length - 2} more`;
}

function packet(id: number, type: number, body: string): Buffer {
  const payload = Buffer.from(body, "utf8");
  // Length counts the id, the type, the body and its two closing zero bytes
  const out = Buffer.alloc(14 + payload.length);
  out.writeInt32LE(10 + payload.length, 0);
  out.writeInt32LE(id, 4);
  out.writeInt32LE(type, 8);
  payload.copy(out, 12);
  return out;
}

/** Signs in to the console and asks one command: its answer, or null when it can't. */
export function rcon(host: string, port: number, password: string, command: string, timeoutMs = RCON_TIMEOUT_MS): Promise<string | null> {
  return new Promise((resolve) => {
    const socket = connect({ host, port });
    let buffer = Buffer.alloc(0);
    let signedIn = false;
    const finish = (value: string | null) => {
      clearTimeout(timer);
      socket.destroy();
      resolve(value);
    };
    const timer = setTimeout(() => finish(null), timeoutMs);
    socket.on("error", () => finish(null));
    socket.on("close", () => finish(null));
    socket.on("connect", () => socket.write(packet(1, LOGIN, password)));
    socket.on("data", (chunk: Buffer) => {
      buffer = Buffer.concat([buffer, chunk]);
      while (buffer.length >= 4) {
        const length = buffer.readInt32LE(0);
        if (length < 10 || length > MAX_PACKET) return finish(null);
        if (buffer.length < 4 + length) return;
        const id = buffer.readInt32LE(4);
        const type = buffer.readInt32LE(8);
        const body = buffer.subarray(12, 2 + length).toString("utf8");
        buffer = buffer.subarray(4 + length);
        if (!signedIn) {
          if (type !== LOGIN_ANSWER) continue;
          if (id === -1) return finish(null);
          signedIn = true;
          socket.write(packet(10, COMMAND, command));
        } else if (id === 10) {
          return finish(body);
        }
      }
    });
  });
}

async function docker(path: string): Promise<Response | null> {
  try {
    const response = await fetch(`http://docker${path}`, { unix: DOCKER_SOCKET, signal: AbortSignal.timeout(DOCKER_TIMEOUT_MS) });
    return response.ok ? response : null;
  } catch {
    return null; // a box with no socket yet
  }
}

interface Container {
  Config?: { Env?: string[] };
  NetworkSettings?: { Networks?: Record<string, { IPAddress?: string }> };
}

/** The app's running container, by compose project, since a later copy's is ix-<app>-2-<app>-2-1. */
async function containerOf(appId: string): Promise<Container | null> {
  const filters = encodeURIComponent(JSON.stringify({ label: [`com.docker.compose.project=ix-${appId}`], status: ["running"] }));
  const listed = (await (await docker(`/containers/json?filters=${filters}`))?.json().catch(() => null)) as Array<{ Id: string }> | null;
  const id = listed?.[0]?.Id;
  return id ? (((await (await docker(`/containers/${id}/json`))?.json().catch(() => null)) as Container | null) ?? null) : null;
}

/** A container's environment as a map. */
export const envOf = (container: Container | null): Map<string, string> =>
  new Map((container?.Config?.Env ?? []).map((pair) => [pair.slice(0, pair.indexOf("=")), pair.slice(pair.indexOf("=") + 1)]));

const addressOf = (container: Container | null): string | null =>
  Object.values(container?.NetworkSettings?.Networks ?? {}).map((network) => network.IPAddress).find(Boolean) ?? null;

export async function run(ctx: WidgetContext): Promise<WidgetQueryResult> {
  const container = await containerOf(ctx.appId);
  const env = envOf(container);
  const address = addressOf(container);
  const password = env.get("RCON_PASSWORD");
  const answer = address && password ? await rcon(address, Number(env.get("RCON_PORT")) || 27015, password, "players") : null;
  const names = answer ? connectedPlayers(answer) : [];
  const max = Number(env.get("MAX_PLAYERS")) || 32;
  const fields: Record<string, WidgetFieldValue> = {
    // One entry while anyone's on: the game in bold, the players in the small line under it
    online: { type: "list", entries: names.length ? [{ title: "Project Zomboid", subtitle: playersLine(names), image: ARTWORK }] : [] },
    count: { type: "stat", label: "Players", value: `${names.length}/${max}` },
  };
  return { fields };
}

// Project Zomboid's key art, from Aaron (2026-11-07): cropped to the card's shape at its center, 660x260, WebP at quality 78.
export const ARTWORK =
  "data:image/webp;base64,";
